/**
 * Authored identities, 28 Days Later–Marble Hornets. Every row is a deliberate
 * vehicle/shape/prop choice; no category, index or hash chooses a design.
 * A canonical reference names the inspiration, not a claim of a 1:1 replica.
 * The resolver adds the current character's existing reference URLs. Additional
 * URLs here document specific references; unreviewed entries remain explicit.
 */
const paint = (color, accent, extra = {}) => ({ color, accent, ...extra });
const vehicle = (referenceVehicle, color, accent, extra = {}) => ({
  sourceKind: 'canonical-vehicle-adaptation', referenceVehicle, color, accent, ...extra
});
const original = (color, accent, extra = {}) => ({
  sourceKind: 'original-universe-design', color, accent, ...extra
});
const design = (label, model, motifs, recognition, options = {}) => Object.freeze({
  label, model,
  motifs: Object.freeze(motifs.split(' ')),
  recognition: Object.freeze(recognition.split('|')),
  sourceKind: 'universe-invention', referenceVehicle: null,
  rationale: options.referenceVehicle
    ? `Adaptation de ${options.referenceVehicle} au cockpit ouvert et au gabarit de course.`
    : `Création de course fondée sur les formes et accessoires de l’univers : ${recognition.split('|').join(', ')}.`,
  referenceScope: options.sourceUrls?.length ? 'vehicle-or-universe-reference' : 'existing-character-and-universe-anchors',
  visualReviewStatus: 'pending-game-scale-review',
  ...options,
  sourceUrls: Object.freeze([...(options.sourceUrls || [])])
});

